`include "trail_defs.vh"

module top_module #(
    parameter WIDTH = `TRAIL_COUNT_WIDTH,
    parameter WARNING_AT = 6
) (
    input wire clk,
    input wire reset,
    input wire arrival,
    output wire [WIDTH-1:0] visitors,
    output wire busy
);
    trail_counter #(
        .WIDTH(WIDTH)
    ) counter (
        .clk(clk),
        .reset(reset),
        .arrival(arrival),
        .visitors(visitors)
    );

    trail_indicator #(
        .WIDTH(WIDTH),
        .WARNING_AT(WARNING_AT)
    ) indicator (
        .visitors(visitors),
        .busy(busy)
    );
endmodule

sourceFiles.counter.v:
`include "trail_defs.vh"

module trail_counter #(
    parameter WIDTH = `TRAIL_COUNT_WIDTH
) (
    input wire clk,
    input wire reset,
    input wire arrival,
    output reg [WIDTH-1:0] visitors
);
    always @(negedge clk) begin
        if (reset) visitors <= 0;
        else if (arrival) visitors <= visitors + 1'b1;
    end
endmodule

sourceFiles.indicator.v:
`include "trail_defs.vh"

module trail_indicator #(
    parameter WIDTH = `TRAIL_COUNT_WIDTH,
    parameter WARNING_AT = 6
) (
    input wire [WIDTH-1:0] visitors,
    output wire busy
);
    assign busy = visitors >= WARNING_AT;
endmodule
